function validate([operations, args]) {
  if (!Array.isArray(operations) || !Array.isArray(args) || operations.length !== args.length) return 'operations and arguments need the same length.';
  if (operations[0] !== 'ThroneInheritance' || !Array.isArray(args[0]) || args[0].length !== 1) return 'Start with ThroneInheritance(kingName).';
  const nameOk = (name) => typeof name === 'string' && /^[a-z]{1,15}$/.test(name);
  if (!nameOk(args[0][0])) return 'Names have 1 to 15 lowercase English letters.';
  const known = new Set([args[0][0]]);
  const dead = new Set();
  let changes = 0;
  let orders = 0;
  for (let i = 1; i < operations.length; i++) {
    const op = operations[i];
    const a = args[i];
    if (!Array.isArray(a)) return 'Each call needs a list of arguments.';
    if (op === 'birth') {
      if (a.length !== 2 || !nameOk(a[0]) || !nameOk(a[1])) return 'birth takes two names of 1 to 15 lowercase letters.';
      if (!known.has(a[0]) || dead.has(a[0])) return 'birth needs a parent who exists and is alive.';
      if (known.has(a[1])) return 'Every child name must be new.';
      known.add(a[1]);
      changes++;
    } else if (op === 'death') {
      if (a.length !== 1 || !nameOk(a[0])) return 'death takes one name of 1 to 15 lowercase letters.';
      if (!known.has(a[0])) return 'death needs someone already in the family.';
      dead.add(a[0]);
      changes++;
    } else if (op === 'getInheritanceOrder') {
      if (a.length !== 0) return 'getInheritanceOrder takes no arguments.';
      orders++;
    } else {
      return 'Only birth, death and getInheritanceOrder can follow the constructor.';
    }
  }
  if (changes > 100000) return 'At most 10^5 calls to birth and death.';
  if (orders > 10) return 'At most 10 calls to getInheritanceOrder.';
  return null;
}

