class ThroneInheritance {
  constructor(kingName) {
    this.king = kingName;
    this.children = new Map([[kingName, []]]);
    this.dead = new Set();
  }

  birth(parentName, childName) {
    this.children.get(parentName).push(childName);
    this.children.set(childName, []);
  }

  death(name) {
    this.dead.add(name);
  }

  getInheritanceOrder() {
    const order = [];
    const stack = [this.king];
    while (stack.length > 0) {
      const person = stack.pop();
      if (!this.dead.has(person)) {
        order.push(person);
      }
      const kids = this.children.get(person);
      for (let i = kids.length - 1; i >= 0; i--) {
        stack.push(kids[i]);
      }
    }
    return order;
  }
}

