class ThroneInheritance {
  constructor(kingName) {
    this.king = kingName;
    this.parentOf = new Map();
    this.kidsOf = new Map();
    this.kidsOf.set(kingName, []);
    this.gone = [];
  }
  birth(parentName, childName) {
    this.parentOf.set(childName, parentName);
    this.kidsOf.get(parentName).push(childName);
    this.kidsOf.set(childName, []);
  }
  death(name) {
    this.gone.push(name);
  }
  getInheritanceOrder() {
    // Follow the Successor rule from the statement literally.
    const line = [this.king];
    const successor = (x) => {
      const next = this.kidsOf.get(x).find(kid => !line.includes(kid));
      if (next !== undefined) return next;
      if (x === this.king) return null;
      return successor(this.parentOf.get(x));
    };
    let current = this.king;
    for (;;) {
      const next = successor(current);
      if (next === null) break;
      line.push(next);
      current = next;
    }
    return line.filter(person => !this.gone.includes(person));
  }
}

