function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const used = new Set();
  const newName = () => {
    for (;;) {
      const length = size === 'large' ? pick(1, 15) : pick(1, 4);
      let name = '';
      for (let i = 0; i < length; i++) name += letters[pick(0, 25)];
      if (!used.has(name)) {
        used.add(name);
        return name;
      }
    }
  };
  const king = newName();
  const operations = ['ThroneInheritance'];
  const args = [[king]];
  const alive = [king];
  let lastBorn = king;
  let orders = 0;
  const total = size === 'large' ? 500 : pick(2, 16);
  const shape = rand(); // below 0.3: mostly a deep chain; below 0.5: mostly the king's children; otherwise random
  const deathRate = size === 'large' ? 0.1 + rand() * 0.3 : 0.3;
  for (let i = 1; i < total; i++) {
    const wantOrder = size === 'large' ? i % 50 === 49 : (i === total - 1 || rand() < 0.2);
    if (wantOrder && orders < 10) {
      operations.push('getInheritanceOrder');
      args.push([]);
      orders++;
      continue;
    }
    if (alive.length === 0) break;
    // Large families always keep someone alive so births can continue.
    if (rand() < deathRate && (size === 'small' || alive.length > 1)) {
      const index = pick(0, alive.length - 1);
      const name = alive[index];
      alive[index] = alive[alive.length - 1];
      alive.pop();
      operations.push('death');
      args.push([name]);
      continue;
    }
    let parent = alive[pick(0, alive.length - 1)];
    if (shape < 0.3 && alive.includes(lastBorn) && rand() < 0.8) parent = lastBorn;
    else if (shape < 0.5 && alive.includes(king) && rand() < 0.7) parent = king;
    const child = newName();
    operations.push('birth');
    args.push([parent, child]);
    alive.push(child);
    lastBorn = child;
  }
  if (orders === 0) {
    operations.push('getInheritanceOrder');
    args.push([]);
  }
  return [operations, args];
}
